export function findById(id){return CONTACTS.find(x=>x.id===id)}
export function search(q){const s=String(q||'').toLowerCase();if(!s)return CONTACTS.slice();return CONTACTS.filter(x=>JSON.stringify(x).toLowerCase().includes(s))}
export function enabledOnly(){return CONTACTS.filter(x=>x.enabled!==false)}
export const COUNT=CONTACTS.length;

